"""Shared helpers for Step 2: load the cleaned master, apply the Insta Help scope exclusion, and define the coding scheme.
All tags are keyword/phrase rules applied to the ORIGINAL text (review_title + review_text). They are analyst-defined, built bottom-up from
reading the reviews (Step 1) and frequency scans, and are NOT human-validated (validation is Step 3)."""
import re
import pandas as pd

MASTER = "output/urban_company_reviews_master.csv"
I = re.I

# ------------------------------------------------------------------ Insta Help exclusion (analysis scope only)
INSTA_NAMED = re.compile(r"insta[\s\-_]*(?:help|maid|house|service|services|pack|gold|booking|bookings|helper|helpers|clean|cook)|instant[\s\-]*(?:help|maid|service|booking)|instamaid|\binsta\b", I)
INSTA_UNNAMED_IDS = {  # reviews that clearly describe an instant house-help booking without using the name (read individually)
    "GP-0418", "GP-0472", "GP-0527", "GP-0659", "GP-0735", "GP-0886", "GP-1032", "GP-1399", "PC-0003", "GP-0507", "GP-0764"}


def load(apply_scope=True):
    df = pd.read_csv(MASTER, encoding="utf-8-sig", keep_default_na=False, dtype=str)
    df["rating_f"] = pd.to_numeric(df.rating, errors="coerce")
    df["text"] = (df.review_title.str.strip() + " " + df.review_text.str.strip()).str.strip()
    df["tl"] = df.text.str.lower()
    df["insta_help"] = (df.text.str.contains(INSTA_NAMED) | df.service_categories_all.str.contains("Insta Help / House Help", regex=False)
                        | df.record_id.isin(INSTA_UNNAMED_IDS))
    df["word_count"] = df.text.map(lambda t: len(re.findall(r"\w+", t)))
    return (df[~df.insta_help].copy().reset_index(drop=True) if apply_scope else df), df


